-- 06_nomencladores / 01_nn_2025.sql
-- Carga del Nomenclador Nacional 2025 (Anexo I) -> nomencladores_argentina
-- Fuente: tools/sources/nn/Nomenclador_Nacional_2025.sql
-- Nota: sin unidad_tipo ni unidad_valor (precios desactualizados)
-- Total de códigos únicos: 3264
-- =============================================================================

SET client_encoding = 'UTF8';
SET search_path = public;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'nomencladores_argentina') THEN
        RAISE EXCEPTION 'Tabla nomencladores_argentina no existe.';
    END IF;
END $$;

ON CONFLICT (tipo_nomenclador, codigo) DO UPDATE
    SET capitulo       = EXCLUDED.capitulo,
        descripcion    = EXCLUDED.descripcion,
        vigencia_desde = EXCLUDED.vigencia_desde,
        activo         = TRUE;

ON CONFLICT (tipo_nomenclador, codigo) DO UPDATE
    SET capitulo       = EXCLUDED.capitulo,
        descripcion    = EXCLUDED.descripcion,
        vigencia_desde = EXCLUDED.vigencia_desde,
        activo         = TRUE;

ON CONFLICT (tipo_nomenclador, codigo) DO UPDATE
    SET capitulo       = EXCLUDED.capitulo,
        descripcion    = EXCLUDED.descripcion,
        vigencia_desde = EXCLUDED.vigencia_desde,
        activo         = TRUE;

ON CONFLICT (tipo_nomenclador, codigo) DO UPDATE
    SET capitulo       = EXCLUDED.capitulo,
        descripcion    = EXCLUDED.descripcion,
        vigencia_desde = EXCLUDED.vigencia_desde,
        activo         = TRUE;

ON CONFLICT (tipo_nomenclador, codigo) DO UPDATE
    SET capitulo       = EXCLUDED.capitulo,
        descripcion    = EXCLUDED.descripcion,
        vigencia_desde = EXCLUDED.vigencia_desde,
        activo         = TRUE;

ON CONFLICT (tipo_nomenclador, codigo) DO UPDATE
    SET capitulo       = EXCLUDED.capitulo,
        descripcion    = EXCLUDED.descripcion,
        vigencia_desde = EXCLUDED.vigencia_desde,
        activo         = TRUE;

ON CONFLICT (tipo_nomenclador, codigo) DO UPDATE
    SET capitulo       = EXCLUDED.capitulo,
        descripcion    = EXCLUDED.descripcion,
        vigencia_desde = EXCLUDED.vigencia_desde,
        activo         = TRUE;

ANALYZE nomencladores_argentina;

SELECT tipo_nomenclador, COUNT(*) AS total
FROM nomencladores_argentina
WHERE activo = TRUE
GROUP BY tipo_nomenclador
ORDER BY total DESC;

DO $$ BEGIN RAISE NOTICE 'Carga Nomenclador Nacional 2025 finalizada.'; END $$;
